# Gated downloads used by the maintained safety panel. Keep planning offline;
# this is a narrow guard for known models, not a claim about arbitrary HF repos.
GATED_JUDGE_MODELS = {"allenai/wildguard", "google/gemma-2b"}
# olmo-eval task families whose datasets are gated, keyed by the task name before "_" or ":".
GATED_TASK_DATASETS = {"gpqa": "Idavidrein/gpqa"}

SCICODE_REFERENCE_SECRET = "SCICODE_H5PY_HOST_PATH"
SCICODE_REFERENCE_HELP = (
    "SciCode arguments.h5py_host_path must be an explicit absolute reference-data file path when set. "
    "Remove arguments.h5py_host_path to use the default SCICODE_H5PY_HOST_PATH Beaker secret, "
    "or replace the placeholder with your actual test_data.h5 path on an evaluator-mounted filesystem. "
    "Override evaluation.secrets.SCICODE_H5PY_HOST_PATH to select a different Beaker secret. "
    "If you do not want SciCode, remove its [[evaluation.tasks]] entry. "
    "Then rerun python -m open_instruct.miles plan <your-run-config> before launching."
)


def parse(value, launch):
    value = dict(value)
    allowed = {
        "mode",
        "interval",
        "initial",
        "final",
        "tasks",
        "image",
        "revision",
        "gpus",
        "cluster",
        "workspace",
        "budget",
        "secrets",
        "submit_timeout",
        "timeout",
        "provider_kwargs",
        "external_server_args",
    }
    if "server_args" in value:
        raise InputError("evaluation.server_args was replaced by provider_kwargs; use SGLang Python option names")
    if set(value) - allowed:
        raise InputError(f"Unknown evaluation fields: {sorted(set(value) - allowed)}")
    mode = value.setdefault("mode", "shared")
    if mode not in ("shared", "background"):
        raise InputError("evaluation.mode must be shared or background")
    if mode == "shared":
        if set(value) != {"mode"}:
            raise InputError(
                "evaluation settings require mode=background; shared evaluation uses existing data/miles fields"
            )
        return value
    defaults = dict(
        interval=20, initial=True, final=True, gpus=1, submit_timeout=30, timeout="3h", secrets={}, provider_kwargs={}
    )
    for key, default in defaults.items():
        value.setdefault(key, default)
    value.setdefault("external_server_args", [])
    for key in ("cluster", "workspace", "budget"):
        value.setdefault(key, launch[key])
    if type(value["interval"]) is not int or value["interval"] < 0:
        raise InputError("evaluation.interval must be a nonnegative integer (0 disables periodic evaluation)")
    for key in ("gpus", "submit_timeout"):
        if type(value[key]) is not int or value[key] < 1:
            raise InputError(f"evaluation.{key} must be a positive integer")
    for key in ("initial", "final"):
        if type(value[key]) is not bool:
            raise InputError(f"evaluation.{key} must be boolean")
    if not isinstance(value.get("image"), str) or not re.fullmatch(r"[0-9A-HJKMNP-TV-Z]{26}", value["image"]):
        raise InputError("evaluation.image must be an immutable Beaker image ID")
    if not isinstance(value.get("revision"), str) or not re.fullmatch(r"[0-9a-f]{40}", value["revision"]):
        raise InputError("evaluation.revision must pin the full olmo-eval Git commit")
    for key in ("cluster", "workspace", "budget", "timeout"):
        if not isinstance(value[key], str) or not value[key].strip():
            raise InputError(f"evaluation.{key} must be a nonempty string")
    secrets = value["secrets"]
    if not isinstance(secrets, dict) or any(
        not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key) or not isinstance(secret, str) or not secret
        for key, secret in secrets.items()
    ):
        raise InputError("evaluation.secrets must map environment names to Beaker secret references")
    value["secrets"] = {
        key: secret for key, secret in launch["secrets"].items() if key in {"WANDB_API_KEY", "HF_TOKEN"}
    } | secrets
    kwargs = value["provider_kwargs"]
    if not isinstance(kwargs, dict) or any(not re.fullmatch(r"[a-z][a-z0-9_]*", key) for key in kwargs):
        raise InputError("evaluation.provider_kwargs must be a table of SGLang Python options")
    reserved = {
        "model",
        "model_name",
        "model_path",
        "tokenizer",

        if any(word in encoded for word in ("api_key", "password", "access_token", "api-key")):
            raise InputError("Use evaluation.secrets for credentials, not task overrides")
    if any(
        task.get("kind") == "external" and task["task"] == "scicode" and "h5py_host_path" not in task["arguments"]
        for task in tasks
    ):
        value["secrets"].setdefault(SCICODE_REFERENCE_SECRET, SCICODE_REFERENCE_SECRET)
    validate_judge_credentials(value)
    return value


def validate_scicode_reference_path(config):
    """Reject unresolved SciCode assets before allocating a training/evaluation job.

    Examples remain loadable for planning. The path belongs to the remote worker,
    so existence is checked there rather than on the submitting workstation.
    """
    for task in config.get("tasks", []):
        if task.get("kind") != "external" or task.get("task") != "scicode":
            continue
        if "h5py_host_path" not in task.get("arguments", {}):
            continue  # The evaluator resolves the default Beaker secret.
        path = task["arguments"]["h5py_host_path"]
        if (
            not isinstance(path, str)
            or not path.strip()
            or path != path.strip()
            or not Path(path).is_absolute()
            or re.search(r"YOUR_[A-Z_]+|[$<>]", path)
        ):
            raise InputError(SCICODE_REFERENCE_HELP)


def validate_judge_credentials(config):
    """Reject known gated managed-judge and dataset downloads without an evaluator secret."""
    if config["secrets"].get("HF_TOKEN", "").strip():
        return
    affected = []
    for task in config["tasks"]:
        if task.get("kind", "task") != "task" or not (config["initial"] or config["final"] or task["interval"] > 0):
            continue
        dataset = GATED_TASK_DATASETS.get(re.split(r"[_:]", task["task"], maxsplit=1)[0])
        if dataset:
            affected.append(f"{task['task']} (dataset={dataset})")
        harness = task.get("harness", {})
        for key, model in harness.items():
            if not re.fullmatch(r"auxiliary_providers\.[^.]+\.(model|tokenizer)", key):
                continue
            provider = key.rsplit(".", 1)[0]
            if (
                isinstance(model, str)
                and model in GATED_JUDGE_MODELS
                and harness.get(f"{provider}.kind") == "vllm_server"
                and not harness.get(f"{provider}.base_url")
            ):
                affected.append(f"{task['task']} ({key}={model})")
    if affected:
        raise InputError(
            "Background evaluation requires an HF_TOKEN Beaker secret reference for gated judges or datasets: "
            + "; ".join(affected)

